'use client';

import { useActionState } from 'react';

async function submitContactForm(
  _prevState: { success?: boolean; errors?: Record<string, string> } | null,
  formData: FormData
) {
  'use server';

  const name = formData.get('name') as string;
  const email = formData.get('email') as string;
  const message = formData.get('message') as string;

  // Validation - check that all fields are provided
  const errors: Record<string, string> = {};
  if (!name || typeof name !== 'string' || name.trim() === '') {
    errors.name = 'Name is required';
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    errors.email = 'Email is required';
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    errors.message = 'Message is required';
  }

  if (Object.keys(errors).length > 0) {
    return { success: false, errors };
  }

  // Simulate saving contact message
  console.log('Contact message received:', { name, email, message });
  return { success: true, errors: {} };
}

export default function ContactForm() {
  const [state, formAction] = useActionState(submitContactForm, null);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input
            id="name"
            name="name"
            type="text"
            placeholder="Your name"
            defaultValue={state?.errors ? '' : undefined}
          />
          {state?.errors?.name && (
            <p style={{ color: 'red', margin: '4px 0 0 0', fontSize: '14px' }}>
              {state.errors.name}
            </p>
          )}
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="Your email"
            defaultValue={state?.errors ? '' : undefined}
          />
          {state?.errors?.email && (
            <p style={{ color: 'red', margin: '4px 0 0 0', fontSize: '14px' }}>
              {state.errors.email}
            </p>
          )}
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea
            id="message"
            name="message"
            placeholder="Your message"
            rows={5}
            defaultValue={state?.errors ? '' : undefined}
          />
          {state?.errors?.message && (
            <p style={{ color: 'red', margin: '4px 0 0 0', fontSize: '14px' }}>
              {state.errors.message}
            </p>
          )}
        </div>
        <button type="submit">Submit</button>
        {state?.success && (
          <p style={{ color: 'green', margin: '8px 0 0 0' }}>
            Thank you! Your message has been sent.
          </p>
        )}
      </form>
    </div>
  );
}

